<?php
namespace ZinCelestial\Platform\Database; defined('ABSPATH')||exit;
final class AtomicLock{private string $name;private string $token='';public function __construct(string $name){$this->name='zcp_'.sanitize_key($name);}public static function table():string{global $wpdb;return $wpdb->base_prefix.'zcp_locks';}public static function install():void{global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$table=self::table();$charset=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $table (lock_name varchar(191) NOT NULL, token char(36) NOT NULL, expires_at bigint unsigned NOT NULL, PRIMARY KEY (lock_name), KEY expires_at (expires_at)) $charset;");}public function acquire(int $ttl=300):bool{global $wpdb;$this->token=wp_generate_uuid4();$now=time();$expires=$now+max(30,$ttl);$table=self::table();$sql=$wpdb->prepare("INSERT INTO $table (lock_name,token,expires_at) VALUES (%s,%s,%d) ON DUPLICATE KEY UPDATE token=IF(expires_at<%d,VALUES(token),token),expires_at=IF(expires_at<%d,VALUES(expires_at),expires_at)",$this->name,$this->token,$expires,$now,$now);if(false===$wpdb->query($sql))return false;$owner=$wpdb->get_var($wpdb->prepare("SELECT token FROM $table WHERE lock_name=%s",$this->name));return is_string($owner)&&hash_equals($this->token,$owner);}public function release():bool{global $wpdb;if(''===$this->token)return false;$r=$wpdb->query($wpdb->prepare('DELETE FROM '.self::table().' WHERE lock_name=%s AND token=%s',$this->name,$this->token));$this->token='';return 1===$r;}public static function prune():void{global $wpdb;$wpdb->query($wpdb->prepare('DELETE FROM '.self::table().' WHERE expires_at<%d',time()));}}
